import{ct as e,n as t,st as n,wt as r}from"./chunks/framework.eUj94whv.js";var i=JSON.parse(`{"title":"XiHan.UI","description":"","frontmatter":{},"headers":[],"relativePath":"en/introduction.md","filePath":"en/introduction.md","lastUpdated":1792956715000}`),a={name:`en/introduction.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="xihan-ui" tabindex="-1">XiHan.UI <a class="header-anchor" href="#xihan-ui" aria-label="Permalink to “XiHan.UI”">​</a></h1><p>XiHan.UI is a framework-agnostic component library: state machines and accessibility logic live in a headless core, and each front-end framework gets only a thin adapter.</p><p>Every component comes as a headless core, a Vue component, a React component, a custom element and a default skin. The layers share one source: the core alone defines behavior, and each adapter wires it into its framework&#39;s rendering and event model.</p><div class="tip custom-block"><p class="custom-block-title">About this English edition</p><p>The English pages cover getting started, theming, accessibility and the API reference of every component. The full documentation, including the remaining guides, usage guidance and live examples, is in <a href="/introduction">Chinese</a>.</p></div><h2 id="how-it-differs-from-typical-component-libraries" tabindex="-1">How it differs from typical component libraries <a class="header-anchor" href="#how-it-differs-from-typical-component-libraries" aria-label="Permalink to “How it differs from typical component libraries”">​</a></h2><p>Most component libraries bind behavior to one framework&#39;s component model: switching frameworks means rewriting everything, and accessibility and keyboard interaction are what a rewrite most easily loses. XiHan.UI separates the two:</p><table tabindex="0"><thead><tr><th>Layer</th><th>Packages</th><th>Responsibility</th></tr></thead><tbody><tr><td>Adapters</td><td><code>@xihan-ui/vue</code>, <code>@xihan-ui/react</code>, <code>@xihan-ui/web-components</code></td><td>Wire the same attributes and behavior into each host</td></tr><tr><td>Headless core</td><td><code>@xihan-ui/headless</code></td><td>Anatomy, state machines and <code>connect</code></td></tr><tr><td>Primitives</td><td><code>@xihan-ui/core</code>, <code>position</code>, <code>motion</code>, <code>pointer</code></td><td>Runtime, positioning, motion and pointer sessions</td></tr><tr><td>Presentation</td><td><code>@xihan-ui/tokens</code>, <code>@xihan-ui/styles</code></td><td>Shared tokens and pure CSS skins</td></tr></tbody></table><p>This gives four verifiable properties:</p><ul><li>One behavior, three hosts. Vue, React and custom elements share the state machine and <code>connect</code>; the documentation site provides examples for each framework, and a demo gate checks the coverage.</li><li>Styling is decoupled from logic. Skins only select <code>data-scope</code> / <code>data-part</code> / <code>data-*</code> state attributes, never frameworks or class names. Replacing the whole skin needs no JS change.</li><li>Accessibility is a criterion. Every component has a machine-readable keyboard specification, and it doubles as the test denominator: a suite that misses one row fails.</li><li>A small dependency surface. The runtime code of the library packages pulls in no third-party dependencies; each adapter depends only on its host framework. Date arithmetic, positioning, syntax highlighting and the Web Components reactive base class are all built in-house.</li></ul><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to “Where to start”">​</a></h2><table tabindex="0"><thead><tr><th>Goal</th><th>Start here</th></tr></thead><tbody><tr><td>Add it to an existing project</td><td><a href="./installation">Installation</a></td></tr><tr><td>Write a first component</td><td><a href="./quickstart">Quick start</a></td></tr><tr><td>Look up a component&#39;s parts, props and keyboard support</td><td><a href="./components/">Components</a></td></tr><tr><td>Change the theme</td><td><a href="./guide/theme">Design tokens and theming</a></td></tr><tr><td>Understand the keyboard and focus contract</td><td><a href="./guide/a11y">Accessibility and keyboard</a></td></tr><tr><td>Read the architecture overview, adapter guides and skin layering</td><td><a href="/overview">Chinese documentation</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to “Related”">​</a></h2><ul><li>Source code: <a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>The two other repositories of the ecosystem: <a href="https://framework.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.Framework</a> and <a href="https://basicapp.docs.xihanfun.com/" target="_blank" rel="noreferrer">XiHan.BasicApp</a></li></ul><div class="tip custom-block"><p class="custom-block-title">Relationship with XiHan.BasicApp</p><p>The front end of XiHan.BasicApp is built on XiHan.UI: since BasicApp v4.0.0 it has been rebuilt on this library, making it the library&#39;s first large consumer in real business code.</p></div>`,14)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};